# Independent census written for this release (no nauty, no code shared with the other checkers): all 2-connected
# graphs of maximum degree <= 3 through order N, generated by ear additions from
# cycles, deduplicated up to isomorphism; counts per order and boundary-6 cores.
import sys, os, warnings, json, time
warnings.filterwarnings('ignore')
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from check import boundary, apsp
import networkx as nx
N=int(sys.argv[1])
def inv(adj):
    D=apsp(adj); n=len(adj)
    prof=[]
    for v in range(n):
        c=[0]*n
        for d in D[v]: c[d]+=1
        nb=sorted(len(adj[w]) for w in adj[v])
        prof.append((len(adj[v]),tuple(nb),tuple(c)))
    return tuple(sorted(prof))
store={}   # (n,m,inv) -> list of adjacency lists
bym={}     # m -> list of adj
def add(adj):
    n=len(adj); m=sum(len(a) for a in adj)//2
    key=(n,m,inv(adj)); L=store.setdefault(key,[])
    if L:
        G=nx.Graph([(u,v) for u in range(n) for v in adj[u] if u<v])
        for H in L:
            if nx.is_isomorphic(G,H): return
        L.append(G)
    else:
        L.append(nx.Graph([(u,v) for u in range(n) for v in adj[u] if u<v]))
    bym.setdefault(m,[]).append(adj)
t0=time.time()
for n in range(3,N+1):
    add([[(i-1)%n,(i+1)%n] for i in range(n)])
m=3
while m in bym or any(k>m for k in bym):
    for adj in bym.get(m,[]):
        n=len(adj); d2=[v for v in range(n) if len(adj[v])<3]
        for i,a in enumerate(d2):
            for b in d2[i+1:]:
                for k in range(0,N-n+1):
                    if k==0 and b in adj[a]: continue
                    new=[list(x) for x in adj]+[[] for _ in range(k)]
                    path=[a]+list(range(n,n+k))+[b]
                    for x,y in zip(path,path[1:]):
                        new[x].append(y); new[y].append(x)
                    add(new)
    bym.pop(m,None); m+=1
from collections import Counter
cnt=Counter(); cores=[]; le6=[]
for (n,mm,_),L in store.items():
    for G in L:
        cnt[n]+=1
        adj=[list(G.neighbors(v)) for v in range(n)]
        bb=len(boundary(adj))
        if bb<=6: le6.append(nx.to_graph6_bytes(G,header=False).decode().strip())
        if bb==6: cores.append((n,nx.to_graph6_bytes(G,header=False).decode().strip()))
print('graphs by order',sorted(cnt.items()),'total',sum(cnt.values()))
print('boundary-6 cores by order',sorted(Counter(n for n,_ in cores).items()))
expected={6:10,7:18,8:49,9:115,10:349,11:1011,12:3421,13:11679,14:43418}
ok=all(cnt[n]==expected[n] for n in expected if n<=N)
print('matches geng -C -D3 counts reported by the upload:',ok,'seconds',round(time.time()-t0))
json.dump(sorted(cores),open(f'ears_cores_{N}.json','w'))
json.dump(sorted(le6),open(f'ears_le6_{N}.json','w'))
cc=dict(Counter(n for n,_ in cores))
assert ok and (N<10 or cc=={6:10,8:1,10:1}), cc
